        const string uiSource="using UnityEngine;using UnityEngine.UI;public class UIState:MonoBehaviour{public Canvas Panel;public Button Action;public bool Visible;public bool CanClick;void Update(){var canvas=gameObject.GetComponent<Canvas>();var button=gameObject.GetComponent<Button>();if(canvas!=null){canvas.enabled=false;Visible=canvas.enabled;}if(button!=null){button.interactable=false;button.enabled=true;CanClick=button.interactable;}}}";
        var uiHeaders=ActorScripts.FromUnity(uiSource);var uiRoundtrip=ActorScripts.ToUnity(uiHeaders);check(uiHeaders.Single().Code.Contains("EM_UiWriteCanvasEnabled")&&uiRoundtrip.Single().Code.Contains("GetComponent<Button>()")&&uiRoundtrip.Single().Code.Contains("button.interactable"),"UI component lookup, serialized references and state writes survive Actor roundtrip");
        using(var notice=System.Text.Json.JsonDocument.Parse("{\"warnings\":[\"UI <script>unsupported</script>\"]}")){var page=ResourcePorting.ResourceHtml(new("run","source","target","verification"),notice.RootElement);check(page.Contains("<h2>지원 범위와 주의 항목</h2>")&&page.Contains("&lt;script&gt;")&&!page.Contains("<script>"),"Engine limitations are visible in the generated report and HTML-encoded");}
        var uiProject=Path.Combine(root,"LegacyUI");var uiModule=Path.Combine(uiProject,"Plugins","EMUIRuntime","Source","EMUIRuntime");Directory.CreateDirectory(Path.Combine(uiModule,"Public"));Directory.CreateDirectory(Path.Combine(uiModule,"Private"));File.WriteAllText(Path.Combine(uiModule,"Public","EMPortUserWidget.h"),LegacyUiRuntimePorting.Header.Replace("\r\n","\n"));File.WriteAllText(Path.Combine(uiModule,"Private","EMPortUserWidget.cpp"),LegacyUiRuntimePorting.Implementation.Replace("\r\n","\n"));UiRuntimePorting.VerifySource(uiProject);check(true,"Legacy runtime UI sources remain readable across LF/CRLF line endings");
        File.WriteAllText(Path.Combine(uiModule,"Private","EMPortUserWidget.cpp"),LegacyUiRuntimePorting.Implementation.Replace("Target->ProcessEvent(Function,nullptr);","return;"));var changedUI=false;try{UiRuntimePorting.VerifySource(uiProject);}catch(NotSupportedException){changedUI=true;}check(changedUI,"Runtime UI callback logic edits are still rejected instead of silently restored");
        var project=Path.Combine(root,"ReferenceAudit");Directory.CreateDirectory(Path.Combine(project,"Assets"));var scene=Path.Combine(project,"Assets","World.unity");File.WriteAllText(scene,"%YAML 1.1\n--- !u!1 &1\nGameObject:\n  m_Parent: {fileID: 999}\n  m_Materials:\n  - {fileID: 2100000, guid: abcdefabcdefabcdefabcdefabcdefab, type: 2}\n");
        const string prefabLookup="using UnityEngine;public class LookupNode:MonoBehaviour{public GameObject Source;public bool Same;void Start(){Same=GetComponent<LookupNode>()==Source.GetComponent<LookupNode>();}}";var lookupHeaders=ActorScripts.FromUnity(prefabLookup);var lookupRestored=ActorScripts.ToUnity(lookupHeaders);check(lookupHeaders.Single().Code.Contains("EM_GetComponent(")&&lookupRestored.Single().Code.Contains("GetComponent<LookupNode>()"),"Read-only component lookup comparisons survive Actor roundtrip");
        var changingLookup=false;try{ActorScripts.FromUnity(prefabLookup.Replace("GetComponent<LookupNode>()","AddComponent<LookupNode>()"));}catch(NotSupportedException){changingLookup=true;}check(changingLookup,"Component creation inside a comparison still requires explicit C# evaluation order");
        var scriptData=JsonNode.Parse("{\"scripts\":[{\"name\":\"Assets/Ordered.cs\",\"guid\":\"1234567890abcdef1234567890abcdef\",\"executionOrder\":-100}]}")!;var scriptPath=Path.Combine(project,"Assets","Ordered.cs");File.WriteAllText(scriptPath,"// metadata fixture");ScriptIdentityPorting.Restore(scriptData,scriptPath,project);var scriptMeta=File.ReadAllText(scriptPath+".meta");check(scriptMeta.Contains("guid: 1234567890abcdef1234567890abcdef")&&scriptMeta.Contains("executionOrder: -100"),"Restored script preserves original GUID and explicit Unity execution order");
        var guidCollision=false;try{ScriptIdentityPorting.Restore(scriptData,scriptPath,project);}catch(InvalidOperationException){guidCollision=true;}check(guidCollision,"Script metadata restoration refuses a GUID already owned by a target asset");
        var invalidGuid=false;scriptData["scripts"]![0]!["guid"]="invalid";try{ScriptIdentityPorting.Restore(scriptData,scriptPath,project);}catch(InvalidOperationException){invalidGuid=true;}check(invalidGuid,"Malformed script identity cannot be written to Unity metadata");
        var identityPackage=Path.Combine(root,"IdentityPackage");Directory.CreateDirectory(identityPackage);var identityUnreal=Path.Combine(root,"IdentityNative");var identityHeaders=Path.Combine(identityUnreal,"Plugins","EMActorPort","Source","EMActorPort","Public");Directory.CreateDirectory(identityHeaders);var identityUnity=Path.Combine(root,"IdentityRestored");Directory.CreateDirectory(Path.Combine(identityUnity,"Assets"));
        var identityCatalog=JsonNode.Parse("[{\"name\":\"Assets/IdentityFirst.cs\",\"source\":\"using UnityEngine;public class IdentityFirst:MonoBehaviour{}\",\"guid\":\"11111111111111111111111111111111\",\"executionOrder\":0},{\"name\":\"Assets/IdentitySecond.cs\",\"source\":\"using UnityEngine;public class IdentitySecond:MonoBehaviour{}\",\"guid\":\"22222222222222222222222222222222\",\"executionOrder\":-100}]")!.AsArray();File.WriteAllText(Path.Combine(identityPackage,"package.json"),new JsonObject{["scripts"]=new JsonArray(identityCatalog[0]!.DeepClone())}.ToJsonString());
        foreach(var file in ActorScripts.FromUnity("using UnityEngine;public class IdentityFirst:MonoBehaviour{}public class IdentitySecond:MonoBehaviour{}"))File.WriteAllText(Path.Combine(identityHeaders,file.Name),file.Code);
        SceneScriptPorting.RestoreInto(identityPackage,identityUnreal,identityUnity,identityCatalog);var identitySecondMeta=File.ReadAllText(Path.Combine(identityUnity,"Assets","EngineMigratorScripts","IdentitySecond.cs.meta"));check(identitySecondMeta.Contains("guid: 22222222222222222222222222222222")&&identitySecondMeta.Contains("executionOrder: -100"),"Project restoration uses every unit's script metadata even when the first unit only defines another script");
        var findings=new List<Finding>();UnityProjectAudit.Add(project,[new("Assets/World.unity","Unity 장면",1)],findings,default);
        check(findings.Any(f=>f.Code=="MISSING_LOCAL_REFERENCE"&&f.SourcePath=="Assets/World.unity"&&f.Line==4&&f.Suggestion!=null),"Broken local references have file, line and repair guidance before engine launch");
        check(findings.Any(f=>f.Code=="EXTERNAL_GUID_UNRESOLVED"&&f.Severity=="미확인"),"Package GUIDs are marked unverified instead of falsely missing");
        var first=Path.Combine(project,"Assets","A.meta");var second=Path.Combine(project,"Assets","B.meta");File.WriteAllText(first,"guid: abcdefabcdefabcdefabcdefabcdefab\n");File.WriteAllText(second,File.ReadAllText(first));findings.Clear();UnityProjectAudit.Add(project,[new("Assets/A.meta","meta",1),new("Assets/B.meta","meta",1)],findings,default);check(findings.Any(f=>f.Code=="DUPLICATE_GUID"),"Duplicate Unity GUID ownership is detected without regenerating metadata");
        var bundle=Path.Combine(root,"ProjectBundle");Directory.CreateDirectory(bundle);var manifest=new JsonObject{["schema"]=1,["blockers"]=new JsonArray(),["units"]=new JsonArray()};
        foreach(var id in new[]{"scene_a","scene_b"}){
            var folder=Path.Combine(bundle,"units",id);Directory.CreateDirectory(Path.Combine(folder,"textures"));File.WriteAllBytes(Path.Combine(folder,"textures","shared.png"),[1,2,3]);
            var data=new JsonObject{["schema"]=1,["blockers"]=new JsonArray(),["nodes"]=new JsonArray(new JsonObject{["id"]="node_0"}),["textures"]=new JsonArray(new JsonObject{["id"]="shared",["name"]="Shared",["file"]="textures/shared.png"}),["meshes"]=new JsonArray(),["materials"]=new JsonArray()};File.WriteAllText(Path.Combine(folder,"package.json"),data.ToJsonString());
            manifest["units"]!.AsArray().Add(new JsonObject{["id"]=id,["name"]="World",["path"]="Assets/"+id+"/World.unity",["package"]="units/"+id,["kind"]="scene",["enabled"]=id=="scene_a"});
        }
        var path=Path.Combine(bundle,"project-package.json");File.WriteAllText(path,manifest.ToJsonString());check(ProjectPorting.ValidatePackages(bundle).Count==2,"Same scene names and local node IDs are scoped by project unit");
        File.WriteAllBytes(Path.Combine(bundle,"units","scene_b","textures","shared.png"),[9,9,9]);var conflict=false;try{ProjectPorting.ValidatePackages(bundle);}catch(InvalidOperationException ex){conflict=ex.Message.Contains("textures:shared");}check(conflict,"Shared texture identity with different actual pixels is blocked before target import");
        manifest["units"]![0]!["package"]="../escape";File.WriteAllText(path,manifest.ToJsonString());var escaped=false;try{ProjectPorting.ValidatePackages(bundle);}catch(InvalidOperationException){escaped=true;}check(escaped,"Project unit paths cannot escape the transfer folder");
        manifest["units"]![0]!["package"]="units/scene_a";File.WriteAllBytes(Path.Combine(bundle,"units","scene_b","textures","shared.png"),[1,2,3]);
        void Travel(string destination){var packagePath=Path.Combine(bundle,"units","scene_a","package.json");var data=JsonNode.Parse(File.ReadAllText(packagePath))!;data["scripts"]=new JsonArray(new JsonObject{["name"]="Assets/Travel.cs",["source"]="using UnityEngine;using UnityEngine.SceneManagement;public class Travel:MonoBehaviour{void Start(){SceneManager.LoadScene("+destination+");}}"});File.WriteAllText(packagePath,data.ToJsonString());File.WriteAllText(path,manifest.ToJsonString());}
        Travel("1");var disabledScene=false;try{ProjectPorting.ValidatePrepared(bundle);}catch(NotSupportedException){disabledScene=true;}check(disabledScene,"Runtime scene indexes cannot target a disabled build scene");
        manifest["units"]![1]!["enabled"]=true;Travel("\"World\"");var duplicateScene=false;try{ProjectPorting.ValidatePrepared(bundle);}catch(NotSupportedException){duplicateScene=true;}check(duplicateScene,"Ambiguous runtime scene names are blocked before creating target maps");
        Travel("1");check(ProjectPorting.ValidatePrepared(bundle)==2,"Validated build-index travel remains supported when scene file names repeat");
        manifest["units"]![1]!["name"]="world";Travel("\"World\"");var caseCollision=false;try{ProjectPorting.ValidatePrepared(bundle);}catch(NotSupportedException){caseCollision=true;}check(caseCollision,"Scene aliases that differ only by case cannot resolve to the wrong Unreal map");manifest["units"]![1]!["name"]="World";Travel("1");
        var prototype=Path.Combine(bundle,"units","prefab_template");Directory.CreateDirectory(prototype);var prototypeData=new JsonObject{["schema"]=1,["blockers"]=new JsonArray(),["textures"]=new JsonArray(),["materials"]=new JsonArray(),["meshes"]=new JsonArray(),["nodes"]=new JsonArray(new JsonObject{["id"]="node_template",["active"]=true})};File.WriteAllText(Path.Combine(prototype,"package.json"),prototypeData.ToJsonString());manifest["units"]!.AsArray().Add(new JsonObject{["id"]="prefab_template",["name"]="Template",["path"]="Assets/Template.prefab",["kind"]="prefab",["enabled"]=false,["package"]="units/prefab_template"});File.WriteAllText(path,manifest.ToJsonString());
        var actorPackage=Path.Combine(bundle,"units","scene_a","package.json");var actorData=JsonNode.Parse(File.ReadAllText(actorPackage))!;var reference=new JsonObject{["name"]="Source",["kind"]="prefab",["value"]="prefab_template"};actorData["nodes"]![0]!["behaviours"]=new JsonArray(new JsonObject{["className"]="Travel",["fields"]=new JsonArray(reference)});File.WriteAllText(actorPackage,actorData.ToJsonString());check(ProjectPorting.ValidatePackages(bundle).Count==3,"Prefab asset references resolve against the project definition catalog");
        reference["value"]="missing_template";File.WriteAllText(actorPackage,actorData.ToJsonString());var missingPrefab=false;try{ProjectPorting.ValidatePackages(bundle);}catch(InvalidOperationException){missingPrefab=true;}check(missingPrefab,"Missing runtime prefab definitions are blocked before target import");
        reference["value"]="prefab_template";File.WriteAllText(actorPackage,actorData.ToJsonString());prototypeData["nodes"]![0]!["hasCamera"]=true;File.WriteAllText(Path.Combine(prototype,"package.json"),prototypeData.ToJsonString());var dynamicPhysics=false;try{ProjectPorting.ValidatePackages(bundle);}catch(NotSupportedException){dynamicPhysics=true;}check(dynamicPhysics,"Untested camera prefab prototypes are explicitly blocked");
        prototypeData["nodes"]![0]!["hasCamera"]=false;prototypeData["nodes"]![0]!["active"]=false;prototypeData["nodes"]![0]!["effectiveActive"]=false;File.WriteAllText(Path.Combine(prototype,"package.json"),prototypeData.ToJsonString());check(ProjectPorting.ValidatePackages(bundle).Count==3,"Dormant mesh/script prefab references preserve inactive flags instead of being rejected before import");
        prototypeData["nodes"]![0]!["hasPhysics"]=true;File.WriteAllText(Path.Combine(prototype,"package.json"),prototypeData.ToJsonString());check(ProjectPorting.ValidatePackages(bundle).Count==3,"Primitive physics prefab references reach native import instead of the former blanket physics blocker");
        prototypeData["nodes"]![0]!["hasAnimation"]=true;File.WriteAllText(Path.Combine(prototype,"package.json"),prototypeData.ToJsonString());check(ProjectPorting.ValidatePackages(bundle).Count==3,"Transform animation prefab references reach native binding and playback import");
        prototypeData["nodes"]![0]!["hasUI"]=true;File.WriteAllText(Path.Combine(prototype,"package.json"),prototypeData.ToJsonString());check(ProjectPorting.ValidatePackages(bundle).Count==3,"UI prefab references reach contextual widget construction instead of the former blanket UI blocker");
        var selfReference=new JsonObject{["name"]="Self",["kind"]="prefab",["value"]="prefab_template"};prototypeData["nodes"]![0]!["behaviours"]=new JsonArray(new JsonObject{["className"]="Travel",["fields"]=new JsonArray(selfReference)});File.WriteAllText(Path.Combine(prototype,"package.json"),prototypeData.ToJsonString());check(ProjectPorting.ValidatePackages(bundle).Count==3,"Prefab definition references may form a self cycle without expanding infinitely");
        selfReference["value"]="missing_transitive";File.WriteAllText(Path.Combine(prototype,"package.json"),prototypeData.ToJsonString());var missingTransitive=false;try{ProjectPorting.ValidatePackages(bundle);}catch(InvalidOperationException){missingTransitive=true;}check(missingTransitive,"Missing transitive prefab definitions remain blocked before creating target maps");selfReference["value"]="prefab_template";File.WriteAllText(Path.Combine(prototype,"package.json"),prototypeData.ToJsonString());
        actorData["nodes"]![0]!["behaviours"]![0]!["id"]="node_0_behaviour_0";reference["kind"]="component";reference["value"]="node_0_behaviour_0";File.WriteAllText(actorPackage,actorData.ToJsonString());check(ProjectPorting.ValidatePackages(bundle).Count==3,"Component references resolve against behaviour identity independently of GameObject identity");
        reference["value"]="missing_component";File.WriteAllText(actorPackage,actorData.ToJsonString());var brokenComponent=false;try{ProjectPorting.ValidatePackages(bundle);}catch(InvalidOperationException ex){brokenComponent=ex.Message.Contains("컴포넌트");}check(brokenComponent,"Missing component references are rejected before creating target objects");
    }
